/**
 * gen-bundles.js — regenerate file://-compatible bundles for AI depth.
 *
 * Browsers can't fetch() or import() local files from file:// pages, so the
 * WASM binary and the ONNX model are embedded as base64 in classic scripts,
 * and the JSEP loader module is inlined for blob-URL import.
 *
 * Usage: node tools/gen-bundles.js   (run from the repo root)
 * Re-run whenever lib/ort-wasm-simd-threaded.jsep.wasm,
 * lib/ort-wasm-simd-threaded.jsep.mjs or
 * models/depth-anything-v2-small-q8.onnx change.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

function chunk(s, n) {
  const out = [];
  for (let i = 0; i < s.length; i += n) out.push(s.slice(i, i + n));
  return out;
}

function writeB64Bundle(outFile, srcRel, varName) {
  const b64 = fs.readFileSync(path.join(ROOT, srcRel)).toString('base64');
  const chunks = chunk(b64, 4 * 1024 * 1024);
  const content =
    '/**\n' +
    ' * GENERATED by tools/gen-bundles.js — do not edit.\n' +
    ' * Base64 of ' + srcRel + ' so AI depth works from file:// (no fetch).\n' +
    ' */\n' +
    'window.' + varName + ' = [\n' +
    chunks.map((c) => "  '" + c + "'").join(',\n') +
    "\n].join('');\n";
  fs.writeFileSync(path.join(ROOT, outFile), content);
  console.log(outFile, (content.length / 1024 / 1024).toFixed(1) + 'MB', chunks.length + ' chunks');
}

// file:// uses the plain single-thread WASM build only (WebGPU's jsep build
// and multi-threading are unavailable there), so only that one is bundled.
writeB64Bundle('lib/ort-wasm-st-bundle.js', 'lib/ort-wasm-simd-threaded.wasm', 'ORT_WASM_ST_B64');
writeB64Bundle('models/model-bundle.js', 'models/depth-anything-v2-small-q8.onnx', 'DEPTH_MODEL_B64');

// Inline loader module (blob-imported at runtime under file://).
function writeInlineLoader(outFile, srcRel, varName) {
  const loader = fs.readFileSync(path.join(ROOT, srcRel), 'utf8');
  const esc = loader.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');
  const content =
    '/**\n' +
    ' * GENERATED by tools/gen-bundles.js — do not edit.\n' +
    ' * Inlined ' + srcRel + ' for blob-URL import under file://.\n' +
    ' */\n' +
    'window.' + varName + ' = `\n' + esc + '\n`;\n';
  fs.writeFileSync(path.join(ROOT, outFile), content);
  console.log(outFile, (content.length / 1024).toFixed(1) + 'KB');
}

writeInlineLoader('lib/ort-st-loader-inline.js', 'lib/ort-wasm-simd-threaded.mjs', 'ORT_ST_LOADER_SRC');
